from typing import List

def triples_sum_to_zero(l: List[int]) -> bool:
    l.sort()
    for i in range(len(l) - 2):
        left, right = i + 1, len(l) - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False

generated_solution:
from typing import List

def triples_sum_to_zero(l: List[int]) -> bool:
    l.sort()
    for i in range(len(l) - 2):
        # Skip duplicates for the first element
        if i > 0 and l[i] == l[i - 1]:
            continue
        left, right = i + 1, len(l) - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                # Ensure distinct elements
                if l[i] != l[left] and l[left] != l[right] and l[i] != l[right]:
                    return True
                else:
                    # Move pointers if duplicates are found
                    if current_sum < 0:
                        left += 1
                    else:
                        right -= 1
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False

