def fibfib(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n <= 1:
        return 0
    if n == 2:
        return 1

    # Initialize the first three numbers
    a, b, c = 0, 0, 1

    # Compute the n-th FibFib number
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c

    return c

