from typing import List

def circular_shift(x: int, shift: int) -> str:
    if x == 0:
        return "0"

    digits: List[str] = list(str(x))
    n = len(digits)
    shift %= n

    if shift == 0:
        return ''.join(digits)

    if shift > n:
        return ''.join(reversed(digits))

    return ''.join(digits[-shift:] + digits[:-shift])

