import math

def is_simple_power(x, n):
    if n <= 0 or x <= 0:
        return False
    if n == 1:
        return x == 1
    try:
        log_result = math.log(x, n)
    except ValueError:  # Handle case where x or n is not positive
        return False
    return log_result == int(log_result)

