def encrypt(s):
    encrypted = ''
    for char in s:
        if char.isalpha():
            shifted = chr((ord(char.lower()) - 97 + 2 * 2) % 26 + 97)
            encrypted += shifted if char.islower() else shifted.upper()
        else:
            encrypted += char
    return encrypted

from typing import List, Optional

def next_smallest(lst: List[int]) -> Optional[int]:
