from typing import Dict

def check_dict_case(dict: Dict) -> bool:
    if not dict:
        return False

    key_types = set()
    for key in dict:
        if isinstance(key, str):
            if key.islower():
                key_types.add('lower')
            elif key.isupper():
                key_types.add('upper')
            else:
                return False
        else:
            return False

    return len(key_types) <= 1

