initial_code:
from typing import List

def f(n: int) -> List[int]:
    def factorial(x: int) -> int:
        return 1 if x == 0 else x * factorial(x - 1)

    def sum_to_i(x: int) -> int:
        return x * (x + 1) // 2

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_i(i))
    return result

