def match_parens(lst: List[str]) -> str:
    def is_balanced(s: str) -> bool:
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    s1, s2 = lst
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    return 'No'

