initial_code:
from typing import List

def get_odd_collatz(n: int) -> List[int]:
    def generate_collatz(start: int) -> List[int]:
        sequence = []
        while start != 1:
            sequence.append(start)
            if start % 2 == 0:
                start = start // 2
            else:
                start = 3 * start + 1
        sequence.append(1)
        return sequence

    collatz_sequence = generate_collatz(n)
    odd_numbers = [num for num in collatz_sequence if num % 2 != 0]
    return sorted(odd_numbers)

