from typing import List

def valid_date(date: str) -> bool:
    # Check if the date string is not empty and in the correct format
    if not date or len(date) != 10 or date[2] != '-' or date[5] != '-':
        return False

    # Split the date into month, day, and year
    try:
        month, day, year = map(int, date.split('-'))
    except ValueError:
        return False

    # Check the validity of the month
    if month < 1 or month > 12:
        return False

    # Check the validity of the day based on the month
    if month in [1, 3, 5, 7, 8, 10, 12]:  # Months with 31 days
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:  # Months with 30 days
        if day < 1 or day > 30:
            return False
    else:  # February
        # Consider leap year for February
        if (year % 4 == 0 and year % 100 != 0) or year % 400 == 0:
            if day < 1 or day > 29:
                return False
        else:
            if day < 1 or day > 28:
                return False

    return True

