from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x: int, y: int, path: List[int]) -> List[int]:
        if len(path) == k:
            return path

        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                candidate = dfs(nx, ny, new_path)
                if candidate and (min_path is None or candidate < min_path):
                    min_path = candidate
        return min_path

    min_path = None
    for i in range(n):
        for j in range(n):
            path = [grid[i][j]]
            candidate = dfs(i, j, path)
            if candidate and (min_path is None or candidate < min_path):
                min_path = candidate
    return min_path

