def is_nested(string: str) -> bool:
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if not stack:
                return False
            if stack[-1] == '[':
                stack.pop()
                if stack:
                    return True
    return False

