from typing import Union

def compare_one(a, b) -> Union[int, float, str, None]:
    # Convert string numbers to float, replacing comma with dot if necessary
    def to_float(x):
        if isinstance(x, str):
            return float(x.replace(',', '.'))
        return float(x)

    # Convert inputs to float for comparison
    a_float = to_float(a)
    b_float = to_float(b)

    # Compare the float values
    if a_float > b_float:
        # Return the original type of a
        return a if isinstance(a, (int, str)) else int(a) if a.is_integer() else a
    elif a_float < b_float:
        # Return the original type of b
        return b if isinstance(b, (int, str)) else int(b) if b.is_integer() else b
    else:
        # Return None if values are equal
        return None

