initial_code:
from typing import List

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def words_in_sentence(sentence: str) -> str:
    words: List[str] = sentence.split()
    prime_words: List[str] = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_words)

