def find_max(words: List[str]) -> str:
    def unique_char_count(word: str) -> int:
        return len(set(word))

    max_unique_count = 0
    max_word = ""

    for word in words:
        count = unique_char_count(word)
        if count > max_unique_count or (count == max_unique_count and word < max_word):
            max_unique_count = count
            max_word = word

    return max_word

